const period = $('Fetch File').first().json.period;
const allItems = $input.all();

const a1Map  = {};
const ta1Map = {};
const a3Map  = {};

for (const item of allItems) {
  const row = item.json;

  // Find the table identifier key and the LA code value
  let tableType = null;
  let code = null;

  for (const [key, val] of Object.entries(row)) {
    if (typeof key === 'string') {
      if (key.startsWith('Table A1')) tableType = 'A1';
      else if (key.startsWith('Table TA1')) tableType = 'TA1';
      else if (key.startsWith('Table A3')) tableType = 'A3';
    }
    if (typeof val === 'string' && /^E0\d/.test(val)) code = val;
  }

  if (!code || !tableType) continue;

  if (tableType === 'A1') {
    a1Map[code] = {
      total_assessments: typeof row['__EMPTY_3'] === 'number' ? row['__EMPTY_3'] : 0,
      owed_duty:         typeof row['__EMPTY_5'] === 'number' ? row['__EMPTY_5'] : 0,
      prevention_duty:   typeof row['__EMPTY_6'] === 'number' ? row['__EMPTY_6'] : 0,
      relief_duty:       typeof row['__EMPTY_8'] === 'number' ? row['__EMPTY_8'] : 0,
    };
  } else if (tableType === 'TA1') {
    ta1Map[code] = {
      households_in_ta: typeof row['__EMPTY_3'] === 'number' ? row['__EMPTY_3'] : 0,
    };
  } else if (tableType === 'A3') {
    a3Map[code] = {
      support_needs_total:    typeof row['__EMPTY_7']  === 'number' ? row['__EMPTY_7']  : 0,
      mental_health:          typeof row['__EMPTY_21'] === 'number' ? row['__EMPTY_21'] : 0,
      learning_disability:    typeof row['__EMPTY_22'] === 'number' ? row['__EMPTY_22'] : 0,
      drug_dependency:        typeof row['__EMPTY_26'] === 'number' ? row['__EMPTY_26'] : 0,
      alcohol_dependency:     typeof row['__EMPTY_27'] === 'number' ? row['__EMPTY_27'] : 0,
      rough_sleeping_history: typeof row['__EMPTY_29'] === 'number' ? row['__EMPTY_29'] : 0,
    };
  }
}

const rows = [];
for (const [code, a1] of Object.entries(a1Map)) {
  const ta1 = ta1Map[code] || {};
  const a3  = a3Map[code]  || {};
  rows.push({
    lad24cd:                code,
    period,
    total_assessments:      a1.total_assessments     ?? 0,
    owed_duty:              a1.owed_duty             ?? 0,
    prevention_duty:        a1.prevention_duty       ?? 0,
    relief_duty:            a1.relief_duty           ?? 0,
    households_in_ta:       ta1.households_in_ta     ?? 0,
    support_needs_total:    a3.support_needs_total   ?? 0,
    mental_health:          a3.mental_health         ?? 0,
    learning_disability:    a3.learning_disability   ?? 0,
    drug_dependency:        a3.drug_dependency       ?? 0,
    alcohol_dependency:     a3.alcohol_dependency    ?? 0,
    rough_sleeping_history: a3.rough_sleeping_history ?? 0,
  });
}

if (rows.length < 200) {
  throw new Error(`Low row count: ${rows.length}. A1:${Object.keys(a1Map).length} TA1:${Object.keys(ta1Map).length} A3:${Object.keys(a3Map).length}`);
}

return [{ json: { period, row_count: rows.length, batch_json: JSON.stringify(rows) } }];

