const raw = $input.first().json.data;
const lines = raw.trim().split('\n');
const rows = lines.slice(1).map(line => {
  const vals = line.match(/(".*?"|[^,]+|(?<=,)(?=,)|^(?=,)|(?<=,)$)/g) || [];
  const clean = v => (v || '').replace(/"/g, '').trim();
  return {
    lad24cd: clean(vals[0]),
    la_name: clean(vals[1]),
    period: clean(vals[2]),
    total_assessments: parseInt(clean(vals[3])) || 0,
    owed_duty: parseInt(clean(vals[4])) || 0,
    prevention_duty: parseInt(clean(vals[5])) || 0,
    relief_duty: parseInt(clean(vals[6])) || 0,
    households_in_ta: parseInt(clean(vals[7])) || 0,
    support_needs_total: parseInt(clean(vals[8])) || 0,
    mental_health: parseInt(clean(vals[9])) || 0,
    learning_disability: parseInt(clean(vals[10])) || 0,
    drug_dependency: parseInt(clean(vals[11])) || 0,
    alcohol_dependency: parseInt(clean(vals[12])) || 0,
    rough_sleeping_history: parseInt(clean(vals[13])) || 0
  };
}).filter(r => r.lad24cd && r.lad24cd.startsWith('E'));

return [{ json: { row_count: rows.length, batch_json: JSON.stringify(rows) } }];
